-- main._specimen_path_surgery_link_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."_specimen_path_surgery_link_v1" AS CREATE VIEW _specimen_path_surgery_link_v1 AS WITH spine AS (SELECT * FROM main._specimen_synoptic_spine_v1), sp AS (SELECT s.*, l.surgery_episode_id, l.path_surgery_id, l.tumor_ordinal, l.linkage_confidence_tier, l.linkage_score, l.score_rank, row_number() OVER (PARTITION BY s.research_id, s.synoptic_row_ix, s.tumor_index ORDER BY l.score_rank NULLS LAST, l.linkage_score DESC NULLS LAST) AS _rk FROM spine AS s LEFT JOIN main.surgery_pathology_linkage_v3 AS l ON (((s.research_id = l.research_id) AND (TRY_CAST(s.tumor_index AS INTEGER) = TRY_CAST(l.tumor_ordinal AS INTEGER)))))SELECT synoptic_row_ix, research_id, surg_date, thyroid_procedure, tumor_index, site_text, histologic_type, surg_date_canonical, encounter_synoptic_row_ix, surg_date_parse_tier, surgery_episode_id, path_surgery_id, tumor_ordinal, linkage_confidence_tier, linkage_score, score_rank FROM sp WHERE (_rk = 1);;

-- main._specimen_synoptic_spine_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."_specimen_synoptic_spine_v1" AS CREATE VIEW _specimen_synoptic_spine_v1 AS WITH stl AS (SELECT * FROM main.synoptic_tumor_long_v1 WHERE (research_id IS NOT NULL)), psq AS (SELECT * FROM main.path_synoptics_encounter_qc_v1), joined AS (SELECT stl.synoptic_row_ix, stl.research_id, stl.surg_date, stl.thyroid_procedure, stl.tumor_index, stl.site AS site_text, stl.histologic_type, psq.surg_date_canonical, psq.encounter_synoptic_row_ix, psq.surg_date_parse_tier, row_number() OVER (PARTITION BY stl.research_id, stl.synoptic_row_ix, stl.tumor_index ORDER BY CASE  WHEN ((main."trim"(lower(COALESCE(CAST(psq.tumor_1_histologic_type AS VARCHAR), ''))) = main."trim"(lower(COALESCE(CAST(stl.histologic_type AS VARCHAR), ''))))) THEN (0) ELSE 1 END, psq.encounter_synoptic_row_ix NULLS LAST) AS _enc_pick FROM stl LEFT JOIN psq ON (((stl.research_id = psq.research_id) AND (main."trim"(COALESCE(CAST(stl.surg_date AS VARCHAR), '')) = main."trim"(COALESCE(CAST(psq.surg_date AS VARCHAR), ''))))))SELECT synoptic_row_ix, research_id, surg_date, thyroid_procedure, tumor_index, site_text, histologic_type, surg_date_canonical, encounter_synoptic_row_ix, surg_date_parse_tier FROM joined WHERE (_enc_pick = 1);;

-- main.canonical_nodule_linkage_study_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."canonical_nodule_linkage_study_v1" AS CREATE VIEW canonical_nodule_linkage_study_v1 AS WITH spine AS (SELECT CAST(i.research_id AS BIGINT) AS research_id, CAST(i.nodule_id AS VARCHAR) AS canonical_nodule_id, CAST(i.exam_id AS VARCHAR) AS imaging_exam_id, i.exam_date AS us_exam_date, TRY_CAST(i.nodule_number AS INTEGER) AS nodule_ordinal, i.laterality AS lobe_laterality, i.location_raw AS source_nodule_site_raw, i.max_dimension_cm AS us_max_size_cm, COALESCE(i.tirads_category, CASE  WHEN ((COALESCE(i.tirads_reported, i.tirads_acr_recalculated) = 1)) THEN ('TR1') WHEN ((COALESCE(i.tirads_reported, i.tirads_acr_recalculated) = 2)) THEN ('TR2') WHEN ((COALESCE(i.tirads_reported, i.tirads_acr_recalculated) = 3)) THEN ('TR3') WHEN ((COALESCE(i.tirads_reported, i.tirads_acr_recalculated) = 4)) THEN ('TR4') WHEN ((COALESCE(i.tirads_reported, i.tirads_acr_recalculated) = 5)) THEN ('TR5') WHEN ((COALESCE(i.tirads_reported, i.tirads_acr_recalculated) = 6)) THEN ('TR5') ELSE NULL END) AS acr_tirads, i.source_table AS imaging_source_table FROM imaging_nodule_master_v1 AS i WHERE (i.exam_date IS NOT NULL)), ifna AS (SELECT s.research_id, s.canonical_nodule_id, s.imaging_exam_id, s.us_exam_date, s.nodule_ordinal, s.lobe_laterality, s.source_nodule_site_raw, s.us_max_size_cm, s.acr_tirads, s.imaging_source_table, ifn.fna_event_date, ifn.fna_episode_id, ifn.match_path, ifn.specimen_match_flag, ifn.n_candidates_for_nodule, ifn.is_primary_link, ifn.ordinal_in_nodule FROM spine AS s LEFT JOIN imaging_fna_linkage_mm_v1 AS ifn ON (((s.research_id = ifn.research_id) AND (s.canonical_nodule_id = ifn.nodule_id) AND (CAST(ifn.is_primary_link AS BOOLEAN) IS NOT DISTINCT FROM CAST('t' AS BOOLEAN))))), fna_row AS (SELECT x.*, fe.fna_date_native AS fna_date, fe.bethesda_category, fe.bethesda_raw, fe.specimen_site_raw AS fna_specimen_site_raw, fe.laterality AS fna_laterality FROM ifna AS x LEFT JOIN fna_episode_master_v2 AS fe ON (((x.fna_episode_id IS NOT NULL) AND (CAST(x.research_id AS BIGINT) = CAST(fe.research_id AS BIGINT)) AND (CAST(x.fna_episode_id AS BIGINT) = CAST(fe.fna_episode_id AS BIGINT))))), fmol AS (SELECT fr.*, fmol.molecular_episode_id, fmol.linkage_confidence_tier AS fna_molecular_linkage_tier, fmol.linkage_score AS fna_molecular_linkage_score, fmol.n_candidates AS fna_molecular_n_candidates, mol.test_date_native AS molecular_test_date, mol.platform AS molecular_platform, mol.result AS molecular_result_raw, mol.overall_result_class AS molecular_result_class FROM fna_row AS fr LEFT JOIN (SELECT * FROM fna_molecular_linkage_v3 WHERE (score_rank = 1)) AS fmol ON (((fr.fna_episode_id IS NOT NULL) AND (CAST(fr.research_id AS BIGINT) = CAST(fmol.research_id AS BIGINT)) AND (CAST(fr.fna_episode_id AS BIGINT) = CAST(fmol.fna_episode_id AS BIGINT)))) LEFT JOIN molecular_test_episode_v2 AS mol ON (((fmol.molecular_episode_id IS NOT NULL) AND (CAST(fmol.research_id AS BIGINT) = CAST(mol.research_id AS BIGINT)) AND (CAST(fmol.molecular_episode_id AS BIGINT) = CAST(mol.molecular_episode_id AS BIGINT))))), preop AS (SELECT fm.*, ps.surgery_episode_id AS surgery_episode_id_linked, ps.surgery_date AS surgery_date_index, ps.linkage_confidence_tier AS preop_surgery_linkage_tier, ps.linkage_score AS preop_surgery_linkage_score, ps.n_candidates AS preop_surgery_n_candidates FROM fmol AS fm LEFT JOIN (SELECT * FROM preop_surgery_linkage_v3 WHERE ((score_rank = 1) AND (preop_type = 'fna'))) AS ps ON (((fm.fna_episode_id IS NOT NULL) AND (CAST(fm.research_id AS BIGINT) = CAST(ps.research_id AS BIGINT)) AND (CAST(fm.fna_episode_id AS BIGINT) = CAST(ps.preop_episode_id AS BIGINT))))), spath AS (SELECT p.*, sp.path_surgery_id, sp.tumor_ordinal AS tumor_ordinal_linked, sp.linkage_confidence_tier AS surgery_pathology_linkage_tier, sp.linkage_score AS surgery_pathology_linkage_score, sp.n_candidates AS surgery_pathology_n_candidates FROM preop AS p LEFT JOIN (SELECT * FROM surgery_pathology_linkage_v3 WHERE (score_rank = 1)) AS sp ON (((p.surgery_episode_id_linked IS NOT NULL) AND (CAST(p.research_id AS BIGINT) = CAST(sp.research_id AS BIGINT)) AND (CAST(p.surgery_episode_id_linked AS BIGINT) = CAST(sp.surgery_episode_id AS BIGINT))))), tumor_joined AS (SELECT spth.*, tum.primary_histology AS final_histology, tum.t_stage AS t_stage_final, tum.n_stage AS n_stage_final, tum.margin_status AS margins_final, (tum.tumor_size_cm * 10.0) AS tumor_size_mm_path, COALESCE(tum.multifocality_flag, (tum.number_of_tumors > 1)) AS multifocal_flag FROM spath AS spth LEFT JOIN tumor_episode_master_v2 AS tum ON (((spth.surgery_episode_id_linked IS NOT NULL) AND (CAST(spth.research_id AS BIGINT) = CAST(tum.research_id AS BIGINT)) AND (CAST(spth.surgery_episode_id_linked AS BIGINT) = CAST(tum.surgery_episode_id AS BIGINT)) AND (CAST(spth.tumor_ordinal_linked AS INTEGER) = CAST(tum.tumor_ordinal AS INTEGER))))), earliest_surg AS (SELECT tj.*, (SELECT min(o.surgery_episode_id) FROM operative_episode_detail_v2 AS o WHERE ((CAST(o.research_id AS BIGINT) = tj.research_id) AND (tj.fna_date IS NOT NULL) AND (o.surgery_date_native IS NOT NULL) AND (o.surgery_date_native >= tj.fna_date))) AS earliest_postfna_surgery_episode_id FROM tumor_joined AS tj)SELECT research_id, lower(md5(concat(CAST(research_id AS VARCHAR), '|', canonical_nodule_id))) AS canonical_row_hash, canonical_nodule_id, lobe_laterality AS laterality, lobe_laterality AS lobe, nodule_ordinal, source_nodule_site_raw, us_exam_date AS us_exam_date_first, us_exam_date AS us_exam_date_last, (us_max_size_cm * 10.0) AS us_max_size_mm, acr_tirads, fna_episode_id, fna_date AS fna_date_first, fna_date AS fna_date_last, bethesda_category AS bethesda_worst, molecular_episode_id, molecular_test_date AS molecular_date, molecular_platform, molecular_result_raw AS molecular_result, surgery_episode_id_linked, surgery_date_index AS surgery_date_index, CASE  WHEN (((lower(COALESCE(final_histology, '')) ~~ '%carcinoma%') OR (lower(COALESCE(final_histology, '')) ~~ '%cancer%') OR (lower(COALESCE(final_histology, '')) ~~ '%ptc%') OR (lower(COALESCE(final_histology, '')) ~~ '%ftc%') OR (lower(COALESCE(final_histology, '')) ~~ '%mtc%') OR (lower(COALESCE(final_histology, '')) ~~ '%atc%') OR (lower(COALESCE(final_histology, '')) ~~ '%pdtc%'))) THEN ('malignant') WHEN ((final_histology IS NOT NULL)) THEN ('non_malignant_or_other') ELSE NULL END AS final_pathology_label, final_histology, tumor_size_mm_path, t_stage_final, n_stage_final, margins_final, multifocal_flag, (lower(COALESCE(final_histology, '')) ~~ '%niftp%') AS niftp_flag, json_object('imaging_source_table', imaging_source_table, 'img_fna', json_object('match_path', match_path, 'specimen_match_flag', specimen_match_flag, 'n_candidates_for_nodule', n_candidates_for_nodule, 'is_primary_link', is_primary_link), 'fna_molecular', json_object('tier', fna_molecular_linkage_tier, 'score', fna_molecular_linkage_score, 'n_candidates', fna_molecular_n_candidates, 'molecular_episode_id', molecular_episode_id), 'preop_surgery', json_object('tier', preop_surgery_linkage_tier, 'score', preop_surgery_linkage_score, 'n_candidates', preop_surgery_n_candidates, 'surgery_episode_id', surgery_episode_id_linked), 'surgery_pathology', json_object('tier', surgery_pathology_linkage_tier, 'score', surgery_pathology_linkage_score, 'n_candidates', surgery_pathology_n_candidates, 'path_surgery_id', path_surgery_id, 'tumor_ordinal', tumor_ordinal_linked)) AS source_lineage_json, least(COALESCE(fna_molecular_linkage_score, 1.0), COALESCE(preop_surgery_linkage_score, 1.0), COALESCE(surgery_pathology_linkage_score, 1.0)) AS deterministic_match_confidence, (((n_candidates_for_nodule IS NOT NULL) AND (n_candidates_for_nodule > 1) AND (NOT COALESCE(is_primary_link, CAST('f' AS BOOLEAN)))) OR ((fna_molecular_n_candidates IS NOT NULL) AND (fna_molecular_n_candidates > 1)) OR ((preop_surgery_n_candidates IS NOT NULL) AND (preop_surgery_n_candidates > 1)) OR ((surgery_pathology_n_candidates IS NOT NULL) AND (surgery_pathology_n_candidates > 1)) OR ((surgery_episode_id_linked IS NOT NULL) AND (earliest_postfna_surgery_episode_id IS NOT NULL) AND (CAST(surgery_episode_id_linked AS INTEGER) != CAST(earliest_postfna_surgery_episode_id AS INTEGER))) OR ((bethesda_category IN (3, 4)) AND (molecular_episode_id IS NULL))) AS manual_review_needed_flag FROM earliest_surg;;

-- main.episode_completeness_summary_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."episode_completeness_summary_v" AS CREATE VIEW episode_completeness_summary_v AS (SELECT 'tumor_episode_master_v2' AS table_name, count_star() AS total_rows, count(DISTINCT research_id) AS unique_patients FROM main.tumor_episode_master_v2) UNION ALL (((SELECT 'molecular_test_episode_v2', count_star(), count(DISTINCT research_id) FROM main.molecular_test_episode_v2) UNION ALL (SELECT 'rai_treatment_episode_v2', count_star(), count(DISTINCT research_id) FROM main.rai_treatment_episode_v2)) UNION ALL (SELECT 'operative_episode_detail_v2', count_star(), count(DISTINCT research_id) FROM main.operative_episode_detail_v2));;

-- main.gold_master_episode_events_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."gold_master_episode_events_v1" AS CREATE VIEW gold_master_episode_events_v1 AS SELECT * FROM main.episode_analysis_resolved_v1_dedup;;

-- main.gold_master_patient_facts_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."gold_master_patient_facts_v1" AS CREATE VIEW gold_master_patient_facts_v1 AS SELECT * FROM main.patient_analysis_resolved_v1;;

-- main.linkage_summary_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."linkage_summary_v" AS CREATE VIEW linkage_summary_v AS SELECT t.research_id, count(DISTINCT t.surgery_episode_id) AS n_tumor_episodes, (SELECT count_star() FROM main.molecular_test_episode_v2 AS m WHERE (m.research_id = t.research_id)) AS n_molecular_episodes, (SELECT count_star() FROM main.rai_treatment_episode_v2 AS r WHERE (r.research_id = t.research_id)) AS n_rai_episodes, (SELECT count_star() FROM main.operative_episode_detail_v2 AS o WHERE (o.research_id = t.research_id)) AS n_operative_episodes FROM main.tumor_episode_master_v2 AS t GROUP BY t.research_id;;

-- main.longitudinal_lab_deduped_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."longitudinal_lab_deduped_v" AS CREATE VIEW longitudinal_lab_deduped_v AS WITH ranked AS (SELECT *, row_number() OVER (PARTITION BY research_id, lab_date, lab_name_standardized, COALESCE(CAST(value_numeric AS VARCHAR), value_raw) ORDER BY CASE  WHEN ((ingestion_wave ~~ 'final_institutional%')) THEN (0) WHEN (((ingestion_wave ~~ 'wave_tg%') OR (ingestion_wave ~~ 'wave_tgab%'))) THEN (1) WHEN (((ingestion_wave ~~ 'wave_1%') OR (ingestion_wave ~~ 'wave_2%'))) THEN (2) ELSE 3 END, source_script DESC) AS _rn FROM main.longitudinal_lab_canonical_v1)SELECT * EXCLUDE (_rn) FROM ranked WHERE (_rn = 1);;

-- main.master_fact_long_verified_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."master_fact_long_verified_v1" AS CREATE VIEW master_fact_long_verified_v1 AS WITH latest_release AS (SELECT release_tag FROM qa.release_manifest ORDER BY TRY_CAST(release_tag AS BIGINT) DESC NULLS LAST, created_at DESC LIMIT 1), review_lookup AS (SELECT research_id, reviewer_domain, reviewer_status, reviewer_verified_by, reviewer_decision_at, reviewer_notes FROM (SELECT research_id, "domain" AS reviewer_domain, verification_status AS reviewer_status, reviewer AS reviewer_verified_by, reviewed_at AS reviewer_decision_at, main."trim"(concat_ws(' | ', "nullif"(main."trim"(COALESCE(reviewer_comment, '')), ''), "nullif"(main."trim"(COALESCE(reason_code, '')), ''), "nullif"(main."trim"(COALESCE(promotion_approved, '')), '')), ' ') AS reviewer_notes, row_number() OVER (PARTITION BY research_id, "domain" ORDER BY reviewed_at DESC NULLS LAST, loaded_at DESC) AS _rn FROM qa.manual_review_queue) AS _mrq WHERE (_rn = 1)), fact_core AS (SELECT f.*, COALESCE("nullif"(main."trim"(CAST(f.extraction_run_id AS VARCHAR)), ''), (SELECT run_id FROM main.note_extraction_runs AS r1 WHERE ((r1.success = CAST('t' AS BOOLEAN)) AND (TRY_CAST(r1.started_at AS TIMESTAMP WITH TIME ZONE) <= TRY_CAST(f.extracted_at AS TIMESTAMP WITH TIME ZONE))) ORDER BY TRY_CAST(r1.started_at AS TIMESTAMP WITH TIME ZONE) DESC LIMIT 1), (SELECT run_id FROM main.note_extraction_runs AS r2 WHERE (r2.success = CAST('t' AS BOOLEAN)) ORDER BY TRY_CAST(r2.started_at AS TIMESTAMP WITH TIME ZONE) ASC LIMIT 1)) AS _resolved_extraction_run_id FROM main.canonical_extracted_fact_long_v2 AS f)SELECT f.research_id, f.fact_id, f.fact_domain AS source_domain, f.note_row_id AS source_object_id, f._resolved_extraction_run_id AS extraction_run_id, r.extractor_build_version, CAST(NULL AS VARCHAR) AS llm_model, r.started_at AS extraction_started_at, f.entity_type, f.entity_value_norm, f.entity_value_raw, f.entity_date, f.present_or_negated, f.confidence, f.linkage_anchor_family, f.inferred_surgery_episode_id, f.ep_source_table, f.ep_distance_days, f.linkage_confidence, f.extraction_method, f.extracted_at, f.source_file_id, f.date_source_type, rv.reviewer_status, rv.reviewer_verified_by, rv.reviewer_decision_at, rv.reviewer_notes, CAST('research_id_domain' AS VARCHAR) AS review_grain, CAST('qa.manual_review_queue' AS VARCHAR) AS review_status_source, concat(CAST(f.research_id AS VARCHAR), '|', CAST(f.fact_domain AS VARCHAR)) AS review_join_key, (SELECT release_tag FROM latest_release) AS release_tag FROM fact_core AS f LEFT JOIN main.note_extraction_runs AS r ON ((r.run_id = f._resolved_extraction_run_id)) LEFT JOIN review_lookup AS rv ON (((rv.research_id = f.research_id) AND (rv.reviewer_domain = f.fact_domain)));;

-- main.master_patient_rollup_verified_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."master_patient_rollup_verified_v1" AS CREATE VIEW master_patient_rollup_verified_v1 AS SELECT f.research_id, count_star() AS total_facts, count(DISTINCT f.source_domain) AS domains_covered, count(DISTINCT f.entity_type) AS unique_entity_types, sum(CASE  WHEN ((f.linkage_anchor_family = 'pathology')) THEN (1) ELSE 0 END) AS pathology_facts, sum(CASE  WHEN ((f.linkage_anchor_family = 'operative')) THEN (1) ELSE 0 END) AS operative_facts, sum(CASE  WHEN ((f.linkage_anchor_family = 'imaging')) THEN (1) ELSE 0 END) AS imaging_facts, sum(CASE  WHEN ((f.linkage_anchor_family = 'molecular')) THEN (1) ELSE 0 END) AS molecular_facts, sum(CASE  WHEN ((f.linkage_anchor_family = 'followup')) THEN (1) ELSE 0 END) AS followup_facts, sum(CASE  WHEN ((f.linkage_anchor_family = 'rai')) THEN (1) ELSE 0 END) AS rai_facts, sum(CASE  WHEN ((f.linkage_anchor_family = 'demographics')) THEN (1) ELSE 0 END) AS demographics_facts, count(f.inferred_surgery_episode_id) AS episode_linked_facts, round(((100.0 * count(f.inferred_surgery_episode_id)) / "nullif"(count_star(), 0)), 1) AS pct_episode_linked, count(f.reviewer_status) AS reviewed_facts, round(((100.0 * count(f.reviewer_status)) / "nullif"(count_star(), 0)), 1) AS pct_reviewed, f.release_tag FROM main.master_fact_long_verified_v1 AS f GROUP BY f.research_id, f.release_tag ORDER BY f.research_id;;

-- main.master_source_lineage_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."master_source_lineage_v1" AS CREATE VIEW master_source_lineage_v1 AS SELECT f.research_id, f.source_domain, f.source_object_id, f.entity_type, f.entity_date, f.extraction_run_id, f.extractor_build_version, f.llm_model, f.extraction_started_at, f.extraction_method, f.extracted_at, f.linkage_anchor_family, f.inferred_surgery_episode_id, f.ep_source_table, f.reviewer_status, f.reviewer_verified_by, f.reviewer_decision_at, f.reviewer_notes, f.review_grain, f.review_status_source, f.review_join_key, f.release_tag FROM main.master_fact_long_verified_v1 AS f ORDER BY f.research_id, f.source_domain, f.extracted_at;;

-- main.molecular_fact_lineage_qa_duplicate_candidates_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_fact_lineage_qa_duplicate_candidates_v" AS CREATE VIEW molecular_fact_lineage_qa_duplicate_candidates_v AS SELECT p.note_fact_id, p.molecular_result_id, p.research_id, p.molecular_family, p.note_event_date, p.assay_event_date, p.date_gap_days, n.entity_type AS note_entity_type, main."substring"(COALESCE(n.entity_value_raw, ''), 1, 200) AS note_value_excerpt, a.entity_type AS assay_entity_type, main."substring"(COALESCE(a.entity_value_raw, ''), 1, 200) AS assay_value_excerpt FROM (SELECT DISTINCT n.fact_id AS note_fact_id, a.molecular_result_id, n.research_id, n.molecular_family, n.event_date AS note_event_date, a.event_date AS assay_event_date, abs(date_diff('day', n.event_date, a.event_date)) AS date_gap_days FROM main.molecular_fact_long_base_v AS n INNER JOIN main.molecular_fact_long_base_v AS a ON (((n.source_stream = 'note_genetics') AND (a.source_stream = 'molecular_results') AND (n.research_id = a.research_id) AND (n.molecular_family = a.molecular_family) AND (n.molecular_family IN ('thyroseq', 'afirma')) AND (n.event_date IS NOT NULL) AND (a.event_date IS NOT NULL) AND (abs(date_diff('day', n.event_date, a.event_date)) <= 21)))) AS p LEFT JOIN main.molecular_fact_long_base_v AS n ON (((p.note_fact_id = n.fact_id) AND (n.source_stream = 'note_genetics'))) LEFT JOIN main.molecular_fact_long_base_v AS a ON (((p.molecular_result_id = a.molecular_result_id) AND (a.source_stream = 'molecular_results')));;

-- main.molecular_fact_long_base_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_fact_long_base_v" AS CREATE VIEW molecular_fact_long_base_v AS WITH mr_live AS (SELECT * FROM main.molecular_results WHERE (superseded_by_molecular_result_id IS NULL)), assay_family AS (SELECT r.*, CASE  WHEN (((r.source_table = '42_afirma_structured_file') OR (lower(COALESCE(r.vendor, '')) ~~ '%veracyte%') OR (COALESCE(r.platform, '') = 'Afirma'))) THEN ('afirma') WHEN (((r.source_table = '41_thyroseq_excel_workbook') OR (lower(COALESCE(r.assay_name, '')) ~~ '%thyroseq%'))) THEN ('thyroseq') ELSE 'other_molecular' END AS molecular_family FROM mr_live AS r), note_molecular AS (SELECT f.research_id, f.fact_id, f.note_row_id, f.entity_type, f.entity_value_raw, f.entity_value_norm, COALESCE(TRY_CAST(f.entity_date AS DATE), TRY_CAST(f.note_date AS DATE)) AS event_date, f.evidence_span, f.extraction_method, f.extracted_at, f.fact_domain, f.linkage_anchor_family, f.inferred_surgery_episode_id, f.ep_distance_days, f.linkage_confidence, f.date_source_type, f.source_file_id AS source_workbook_or_table, 'note_derived' AS fact_provenance_category, CASE  WHEN ((f.entity_type ~~* 'thyroseq%')) THEN ('thyroseq') WHEN ((f.entity_type ~~* 'afirma%')) THEN ('afirma') WHEN ((f.entity_type IN ('mutation_panel', 'molecular_risk_category', 'serial_molecular_test', 'bethesda_category', 'fna_adequacy', 'fna_nodule_location', 'fna_cytology_detail'))) THEN ('thyroseq') ELSE 'other_molecular' END AS molecular_family, 'note_genetics' AS source_stream, CAST(NULL AS VARCHAR) AS molecular_result_id, CAST(NULL AS VARCHAR) AS molecular_variant_id, CAST(NULL AS VARCHAR) AS test_date_native, CAST(NULL AS VARCHAR) AS risk_call, CAST(NULL AS VARCHAR) AS source_table, CAST(NULL AS VARCHAR) AS assay_lineage_id FROM main.canonical_extracted_fact_long_v2 AS f WHERE ((f.fact_domain = 'genetics') AND ((f.entity_type ~~* 'thyroseq%') OR (f.entity_type ~~* 'afirma%') OR (f.entity_type IN ('mutation_panel', 'molecular_risk_category', 'serial_molecular_test', 'bethesda_category', 'fna_adequacy', 'fna_nodule_location', 'fna_cytology_detail'))))), assay_envelope_facts AS (SELECT r.research_id, r.molecular_result_id AS fact_id, CAST(NULL AS VARCHAR) AS note_row_id, CASE  WHEN ((r.molecular_family = 'afirma')) THEN ('afirma_result') WHEN ((r.molecular_family = 'thyroseq')) THEN ('thyroseq_result') ELSE 'assay_envelope' END AS entity_type, COALESCE(r.interpretation_summary, r.risk_call, r.canonical_hgvs) AS entity_value_raw, COALESCE(r.interpretation_summary, r.risk_call, r.canonical_hgvs) AS entity_value_norm, r.test_date_parsed AS event_date, CAST(NULL AS VARCHAR) AS evidence_span, CAST('structured_import' AS VARCHAR) AS extraction_method, CAST(r.ingestion_ts AS VARCHAR) AS extracted_at, 'genetics' AS fact_domain, 'molecular' AS linkage_anchor_family, CAST(NULL AS BIGINT) AS inferred_surgery_episode_id, CAST(NULL AS BIGINT) AS ep_distance_days, CAST(NULL AS DOUBLE) AS linkage_confidence, CAST('assay_vendor_record' AS VARCHAR) AS date_source_type, r.source_table AS source_workbook_or_table, 'assay_structured_import' AS fact_provenance_category, r.molecular_family, 'molecular_results' AS source_stream, r.molecular_result_id, CAST(NULL AS VARCHAR) AS molecular_variant_id, r.test_date_native, r.risk_call, r.source_table, r.lineage_id AS assay_lineage_id FROM assay_family AS r), variant_facts AS (SELECT v.research_id, v.molecular_variant_id AS fact_id, CAST(NULL AS VARCHAR) AS note_row_id, CASE  WHEN ((af.molecular_family = 'afirma')) THEN ('afirma_xpression_atlas') ELSE 'thyroseq_mutations' END AS entity_type, COALESCE(v.protein_hgvs, v.canonical_hgvs, v.cdna_hgvs, v.genomic_hgvs, v.raw_variant_token, v.gene_symbol) AS entity_value_raw, COALESCE(v.protein_hgvs, v.canonical_hgvs, v.cdna_hgvs, v.genomic_hgvs, v.raw_variant_token, v.gene_symbol) AS entity_value_norm, af.test_date_parsed AS event_date, CAST(NULL AS VARCHAR) AS evidence_span, CAST('structured_import' AS VARCHAR) AS extraction_method, CAST(v.ingestion_ts AS VARCHAR) AS extracted_at, 'genetics' AS fact_domain, 'molecular' AS linkage_anchor_family, CAST(NULL AS BIGINT) AS inferred_surgery_episode_id, CAST(NULL AS BIGINT) AS ep_distance_days, CAST(NULL AS DOUBLE) AS linkage_confidence, CAST('assay_vendor_record' AS VARCHAR) AS date_source_type, af.source_table AS source_workbook_or_table, 'assay_structured_import' AS fact_provenance_category, af.molecular_family, 'molecular_variant_long' AS source_stream, v.molecular_result_id, v.molecular_variant_id, af.test_date_native, CAST(NULL AS VARCHAR) AS risk_call, af.source_table, v.lineage_id AS assay_lineage_id FROM main.molecular_variant_long AS v INNER JOIN assay_family AS af ON ((v.molecular_result_id = af.molecular_result_id))), stacked_full AS ((SELECT research_id, fact_id, note_row_id, entity_type, entity_value_raw, entity_value_norm, event_date, evidence_span, extraction_method, extracted_at, fact_domain, linkage_anchor_family, inferred_surgery_episode_id, ep_distance_days, linkage_confidence, date_source_type, source_workbook_or_table, fact_provenance_category, molecular_family, source_stream, molecular_result_id, molecular_variant_id, test_date_native, risk_call, source_table, assay_lineage_id FROM note_molecular) UNION ALL ((SELECT research_id, fact_id, note_row_id, entity_type, entity_value_raw, entity_value_norm, event_date, evidence_span, extraction_method, extracted_at, fact_domain, linkage_anchor_family, inferred_surgery_episode_id, ep_distance_days, linkage_confidence, date_source_type, source_workbook_or_table, fact_provenance_category, molecular_family, source_stream, molecular_result_id, molecular_variant_id, test_date_native, risk_call, source_table, assay_lineage_id FROM assay_envelope_facts) UNION ALL (SELECT research_id, fact_id, note_row_id, entity_type, entity_value_raw, entity_value_norm, event_date, evidence_span, extraction_method, extracted_at, fact_domain, linkage_anchor_family, inferred_surgery_episode_id, ep_distance_days, linkage_confidence, date_source_type, source_workbook_or_table, fact_provenance_category, molecular_family, source_stream, molecular_result_id, molecular_variant_id, test_date_native, risk_call, source_table, assay_lineage_id FROM variant_facts))), pair AS (SELECT DISTINCT n.fact_id AS note_fact_id, a.molecular_result_id, n.research_id, n.molecular_family, n.event_date AS note_event_date, a.event_date AS assay_event_date, abs(date_diff('day', n.event_date, a.event_date)) AS date_gap_days FROM note_molecular AS n INNER JOIN assay_envelope_facts AS a ON (((n.research_id = a.research_id) AND (n.molecular_family = a.molecular_family) AND (n.molecular_family IN ('thyroseq', 'afirma')) AND (n.event_date IS NOT NULL) AND (a.event_date IS NOT NULL) AND (abs(date_diff('day', n.event_date, a.event_date)) <= 21)))), note_has_assay AS (SELECT note_fact_id, bool_or(CAST('t' AS BOOLEAN)) AS has_structured_assay_match, min(date_gap_days) AS best_gap_days, arg_min(molecular_result_id, date_gap_days) AS best_molecular_result_id FROM pair GROUP BY note_fact_id), assay_has_note AS (SELECT molecular_result_id, bool_or(CAST('t' AS BOOLEAN)) AS has_note_support, min(date_gap_days) AS best_note_gap_days FROM pair GROUP BY molecular_result_id)SELECT s.*, nh.has_structured_assay_match AS note_matched_structured_assay, nh.best_gap_days AS note_to_assay_gap_days, nh.best_molecular_result_id AS matched_molecular_result_id, hn.has_note_support AS assay_has_note_support, hn.best_note_gap_days AS assay_to_note_gap_days, CASE  WHEN (((s.source_stream = 'note_genetics') AND COALESCE(nh.has_structured_assay_match, CAST('f' AS BOOLEAN)))) THEN ('supporting_note_evidence') WHEN (((s.source_stream IN ('molecular_results', 'molecular_variant_long')) AND COALESCE(hn.has_note_support, CAST('f' AS BOOLEAN)))) THEN ('primary_assay_record') WHEN ((s.source_stream = 'note_genetics')) THEN ('standalone_note') ELSE 'standalone_assay' END AS record_role, CASE  WHEN (((s.source_stream = 'note_genetics') AND COALESCE(nh.has_structured_assay_match, CAST('f' AS BOOLEAN)))) THEN (CAST('f' AS BOOLEAN)) ELSE CAST('t' AS BOOLEAN) END AS included_in_primary_analytics, CAST(CASE  WHEN (((s.source_stream = 'note_genetics') AND COALESCE(nh.has_structured_assay_match, CAST('f' AS BOOLEAN)))) THEN ('structured_assay_supersedes_note_row') WHEN (((s.source_stream IN ('molecular_results', 'molecular_variant_long')) AND COALESCE(hn.has_note_support, CAST('f' AS BOOLEAN)))) THEN ('note_retained_as_supporting_context') ELSE NULL END AS VARCHAR) AS precedence_rationale FROM stacked_full AS s LEFT JOIN note_has_assay AS nh ON (((s.fact_id = nh.note_fact_id) AND (s.source_stream = 'note_genetics'))) LEFT JOIN assay_has_note AS hn ON (((s.molecular_result_id = hn.molecular_result_id) AND (s.source_stream IN ('molecular_results', 'molecular_variant_long'))));;

-- main.molecular_fact_long_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_fact_long_v" AS CREATE VIEW molecular_fact_long_v AS WITH review AS (SELECT research_id, "domain", verification_status AS genetics_review_status, reviewer, reviewed_at FROM (SELECT research_id, "domain", verification_status, reviewer, reviewed_at, row_number() OVER (PARTITION BY research_id ORDER BY reviewed_at DESC NULLS LAST, loaded_at DESC) AS rn FROM qa.manual_review_queue WHERE (lower(COALESCE("domain", '')) = 'genetics')) AS x WHERE (rn = 1))SELECT b.research_id, b.fact_id, b.note_row_id, b.entity_type, b.entity_value_raw, b.entity_value_norm, b.event_date, b.evidence_span, b.extraction_method, b.extracted_at, b.fact_domain, b.linkage_anchor_family, b.inferred_surgery_episode_id, b.ep_distance_days, b.linkage_confidence, b.date_source_type, b.source_workbook_or_table, b.fact_provenance_category, b.molecular_family, b.source_stream, b.molecular_result_id, b.molecular_variant_id, b.test_date_native, b.risk_call, b.source_table, b.assay_lineage_id, b.note_matched_structured_assay, b.note_to_assay_gap_days, b.matched_molecular_result_id, b.assay_has_note_support, b.assay_to_note_gap_days, b.record_role, b.included_in_primary_analytics, b.precedence_rationale, r.genetics_review_status, r.reviewer AS genetics_reviewer, r.reviewed_at AS genetics_reviewed_at, CASE  WHEN (((r.genetics_review_status ~~* '%verified%') OR (r.genetics_review_status ~~* '%approved%'))) THEN ('manual_adjudicated_effective') WHEN ((r.genetics_review_status IS NOT NULL)) THEN ('manual_review_present') ELSE NULL END AS human_review_overlay FROM main.molecular_fact_long_base_v AS b LEFT JOIN review AS r ON ((b.research_id = r.research_id));;

-- main.molecular_normalization_review_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_normalization_review_v1" AS CREATE VIEW molecular_normalization_review_v1 AS SELECT * FROM main.molecular_results WHERE ((normalization_status IN ('quarantine', 'pending_review')) OR (parse_status IN ('partial', 'failed')));;

-- main.molecular_patient_rollup_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_patient_rollup_v" AS CREATE VIEW molecular_patient_rollup_v AS SELECT r.research_id, CAST(count(DISTINCT r.molecular_result_id) AS BIGINT) AS n_molecular_results, CAST(count(DISTINCT v.molecular_variant_id) AS BIGINT) AS n_variant_calls, max(r.test_date_parsed) AS latest_test_date_parsed, min(r.ingestion_ts) AS earliest_result_ingestion_ts, max(r.ingestion_ts) AS latest_result_ingestion_ts, CAST(count(DISTINCT r.source_table) AS BIGINT) AS n_distinct_source_tables, CAST(count(DISTINCT r.assay_name) AS BIGINT) AS n_distinct_assay_names, max(r.panel_version) AS max_panel_version_observed, CAST(count_star() FILTER (WHERE (lower(main."trim"(COALESCE(CAST(r.parse_status AS VARCHAR), ''))) IN ('partial', 'failed', 'pending'))) AS BIGINT) AS n_results_parse_review FROM main.molecular_results_contract_v AS r LEFT JOIN main.molecular_variant_long AS v ON ((v.molecular_result_id = r.molecular_result_id)) GROUP BY r.research_id;;

-- main.molecular_qc_summary_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_qc_summary_v" AS CREATE VIEW molecular_qc_summary_v AS SELECT COALESCE(source_table, '(unknown)') AS source_table, parse_status, normalization_status, CAST(count_star() AS BIGINT) AS n_results, CAST(count(DISTINCT research_id) AS BIGINT) AS n_patients, CAST(count_star() FILTER (WHERE (payload_checksum IS NULL)) AS BIGINT) AS n_missing_payload_checksum, CAST(count_star() FILTER (WHERE (main."trim"(COALESCE(CAST(lineage_id AS VARCHAR), '')) = '')) AS BIGINT) AS n_blank_lineage_id, CAST(count_star() FILTER (WHERE (qc_flags IS NOT NULL)) AS BIGINT) AS n_with_qc_flags FROM main.molecular_results WHERE (superseded_by_molecular_result_id IS NULL) GROUP BY 1, 2, 3;;

-- main.molecular_results_contract_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_results_contract_v" AS CREATE VIEW molecular_results_contract_v AS SELECT molecular_result_id, research_id, source_patient_id, source_specimen_id, source_accession, assay_name, panel_version, platform, vendor, loinc_code, test_date_native, test_date_parsed, interpretation_summary, risk_call, canonical_hgvs, raw_payload_json, payload_checksum, parse_status, normalization_status, qc_flags, lineage_id, ingestion_ts, ingestion_run_id, source_table, source_row_fingerprint, molecular_episode_id, superseded_by_molecular_result_id FROM main.molecular_results WHERE (superseded_by_molecular_result_id IS NULL);;

-- main.molecular_results_contract_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_results_contract_v1" AS CREATE VIEW molecular_results_contract_v1 AS SELECT molecular_result_id, research_id, source_patient_id, source_specimen_id, source_accession, assay_name, panel_version, platform, vendor, loinc_code, test_date_native, test_date_parsed, interpretation_summary, risk_call, canonical_hgvs, raw_payload_json, payload_checksum, parse_status, normalization_status, qc_flags, lineage_id, ingestion_ts, ingestion_run_id, source_table, source_row_fingerprint, molecular_episode_id, superseded_by_molecular_result_id FROM main.molecular_results;;

-- main.molecular_results_enriched_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_results_enriched_v1" AS CREATE VIEW molecular_results_enriched_v1 AS SELECT r.*, (SELECT CAST(count_star() AS BIGINT) FROM main.molecular_variant_long AS v WHERE (v.molecular_result_id = r.molecular_result_id)) AS n_variants_long FROM main.molecular_results AS r;;

-- main.molecular_results_unified_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_results_unified_v" AS CREATE VIEW molecular_results_unified_v AS SELECT * FROM main.molecular_fact_long_v;;

-- main.molecular_variant_contract_v
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_variant_contract_v" AS CREATE VIEW molecular_variant_contract_v AS SELECT v.molecular_variant_id, v.molecular_result_id, v.research_id, v.gene_symbol, v.transcript_id, v.genomic_hgvs, v.cdna_hgvs, v.protein_hgvs, v.canonical_hgvs, v.variant_class, v.allele_fraction, v.zygosity, v.interpretation_text, v.risk_call, v.parse_status, v.normalization_status, v.qc_flags, v.lineage_id, v.ingestion_ts, v.partner_gene_symbol, v.fusion_partner, v.raw_variant_token FROM main.molecular_variant_long AS v INNER JOIN main.molecular_results_contract_v AS r ON ((v.molecular_result_id = r.molecular_result_id));;

-- main.molecular_variant_long_contract_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."molecular_variant_long_contract_v1" AS CREATE VIEW molecular_variant_long_contract_v1 AS SELECT molecular_variant_id, molecular_result_id, research_id, gene_symbol, transcript_id, genomic_hgvs, cdna_hgvs, protein_hgvs, canonical_hgvs, variant_class, allele_fraction, zygosity, interpretation_text, risk_call, parse_status, normalization_status, qc_flags, lineage_id, ingestion_ts, partner_gene_symbol, fusion_partner, raw_variant_token FROM main.molecular_variant_long;;

-- main.notes_entity_summary
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."notes_entity_summary" AS CREATE VIEW notes_entity_summary AS WITH all_entities AS ((SELECT research_id, 'staging' AS "domain", entity_value_norm, present_or_negated FROM note_entities_staging) UNION ALL ((((SELECT research_id, 'genetics' AS "domain", entity_value_norm, present_or_negated FROM note_entities_genetics) UNION ALL (SELECT research_id, 'procedures' AS "domain", entity_value_norm, present_or_negated FROM note_entities_procedures)) UNION ALL ((SELECT research_id, 'operative_detail' AS "domain", entity_value_norm, present_or_negated FROM note_entities_operative_detail) UNION ALL (SELECT research_id, 'complications' AS "domain", entity_value_norm, present_or_negated FROM note_entities_complications))) UNION ALL ((SELECT research_id, 'medications' AS "domain", entity_value_norm, present_or_negated FROM note_entities_medications) UNION ALL (SELECT research_id, 'problem_list' AS "domain", entity_value_norm, present_or_negated FROM note_entities_problem_list))))SELECT CAST(research_id AS VARCHAR) AS research_id, count_star() AS n_entities_total, sum(CASE  WHEN (("domain" = 'staging')) THEN (1) ELSE 0 END) AS n_staging, sum(CASE  WHEN (("domain" = 'genetics')) THEN (1) ELSE 0 END) AS n_genetics, sum(CASE  WHEN (("domain" = 'procedures')) THEN (1) ELSE 0 END) AS n_procedures, sum(CASE  WHEN (("domain" = 'operative_detail')) THEN (1) ELSE 0 END) AS n_operative_detail, sum(CASE  WHEN (("domain" = 'complications')) THEN (1) ELSE 0 END) AS n_complications, sum(CASE  WHEN (("domain" = 'medications')) THEN (1) ELSE 0 END) AS n_medications, sum(CASE  WHEN (("domain" = 'problem_list')) THEN (1) ELSE 0 END) AS n_problem_list, sum(CASE  WHEN ((present_or_negated = 'present')) THEN (1) ELSE 0 END) AS n_present, sum(CASE  WHEN ((present_or_negated = 'negated')) THEN (1) ELSE 0 END) AS n_negated FROM all_entities GROUP BY research_id;;

-- main.path_synoptics_encounter_qc_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."path_synoptics_encounter_qc_v1" AS CREATE VIEW path_synoptics_encounter_qc_v1 AS WITH base AS (SELECT p.*, COALESCE(TRY_CAST(p.surg_date AS DATE), TRY_CAST(main."trim"(CAST(p.surg_date AS VARCHAR)) AS DATE), CAST(try_strptime(main."trim"(CAST(p.surg_date AS VARCHAR)), '%m/%d/%Y') AS DATE), CAST(try_strptime(main."trim"(CAST(p.surg_date AS VARCHAR)), '%m/%d/%y') AS DATE), CAST(try_strptime(main."trim"(CAST(p.surg_date AS VARCHAR)), '%Y-%m-%d') AS DATE)) AS surg_date_canonical, CASE  WHEN ((TRY_CAST(p.surg_date AS DATE) IS NOT NULL)) THEN ('native_cast') WHEN ((TRY_CAST(main."trim"(CAST(p.surg_date AS VARCHAR)) AS DATE) IS NOT NULL)) THEN ('trim_cast') WHEN ((try_strptime(main."trim"(CAST(p.surg_date AS VARCHAR)), '%m/%d/%Y') IS NOT NULL)) THEN ('us_mdy_4digit') WHEN ((try_strptime(main."trim"(CAST(p.surg_date AS VARCHAR)), '%m/%d/%y') IS NOT NULL)) THEN ('us_mdy_2digit') WHEN ((try_strptime(main."trim"(CAST(p.surg_date AS VARCHAR)), '%Y-%m-%d') IS NOT NULL)) THEN ('iso_after_trim') WHEN ((length(COALESCE(main."trim"(CAST(p.surg_date AS VARCHAR)), '')) = 0)) THEN ('empty') ELSE 'unresolved' END AS surg_date_parse_tier FROM path_synoptics AS p WHERE (p.research_id IS NOT NULL))SELECT b.*, row_number() OVER (PARTITION BY b.research_id, b.surg_date_canonical ORDER BY main."trim"(CAST(b.tumor_1_ln_examined AS VARCHAR)), main."trim"(CAST(b.tumor_1_ln_involved AS VARCHAR)), main."trim"(CAST(b.tumor_1_histologic_type AS VARCHAR)), main."trim"(CAST(b.thyroid_procedure AS VARCHAR))) AS encounter_synoptic_row_ix FROM base AS b;;

-- main.v_canonical_us_nodule_scope_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_canonical_us_nodule_scope_v1" AS CREATE VIEW v_canonical_us_nodule_scope_v1 AS SELECT CAST('COMPLETE_MULTI_SHEET_ULTRASOUND_REPORTS.xlsx→raw_us_tirads_excel_v1→imaging_nodule_master_v1' AS VARCHAR) AS canonical_corpus, CAST(count_star() AS BIGINT) AS n_nodule_rows, CAST(count(DISTINCT source_table) AS BIGINT) AS n_distinct_source_table, CAST(min(source_table) AS VARCHAR) AS source_table_example FROM imaging_nodule_master_v1;;

-- main.v_fna_bethesda_episode_vs_resolved_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_fna_bethesda_episode_vs_resolved_v1" AS CREATE VIEW v_fna_bethesda_episode_vs_resolved_v1 AS SELECT e.research_id, e.fna_episode_id, e.bethesda_category AS bethesda_in_episode_master, r.bethesda_resolved_num, r.bethesda_episode_num, r.bethesda_cytology_num, r.bethesda_value_source, r.bethesda_unscorable_reason, CASE  WHEN ((e.bethesda_category IS NOT NULL)) THEN ('episode_master_numeric') WHEN ((r.bethesda_resolved_num IS NOT NULL)) THEN ('resolved_from_episode_or_cytology') ELSE 'unscorable_see_reason' END AS bethesda_analysis_bucket FROM fna_episode_master_v2 AS e LEFT JOIN v_fna_episode_bethesda_resolved_v1 AS r ON (((CAST(e.research_id AS BIGINT) = CAST(r.research_id AS BIGINT)) AND (CAST(e.fna_episode_id AS BIGINT) = CAST(r.fna_episode_id AS BIGINT))));;

-- main.v_fna_bethesda_surface
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_fna_bethesda_surface" AS CREATE VIEW v_fna_bethesda_surface AS SELECT fem.research_id, fem.fna_episode_id, fem.resolved_fna_date, fem.laterality, fem.specimen_site_raw, fem.bethesda_raw, fem.bethesda_category, fc.bethesda_2010_num, fc.bethesda_2010_name, fc.bethesda_2015_num, fc.bethesda_2015_name, fc.bethesda_2023_num, fc.bethesda_2023_name, fc.confidence, fc."method", fc.subtype, fc.path_text_length, CASE  WHEN ((fc.research_id IS NOT NULL)) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS has_cytology_match FROM fna_episode_master_v2 AS fem LEFT JOIN fna_cytology AS fc ON (((CAST(fc.research_id AS INTEGER) = fem.research_id) AND (fc.fna_index = fem.fna_episode_id)));;

-- main.v_fna_episode_bethesda_resolved_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_fna_episode_bethesda_resolved_v1" AS CREATE VIEW v_fna_episode_bethesda_resolved_v1 AS WITH cy AS (SELECT research_id, fna_index, category_num, row_number() OVER (PARTITION BY research_id, fna_index ORDER BY confidence DESC NULLS LAST, ingested_at_utc DESC NULLS LAST) AS rn FROM fna_cytology)SELECT e.research_id, e.fna_episode_id, e.resolved_fna_date, e.bethesda_raw, e.bethesda_category AS bethesda_episode_num, c.category_num AS bethesda_cytology_num, COALESCE(e.bethesda_category, c.category_num) AS bethesda_resolved_num, CASE  WHEN ((e.bethesda_category IS NOT NULL)) THEN ('fna_episode_master_v2') WHEN ((c.category_num IS NOT NULL)) THEN ('fna_cytology_join') ELSE NULL END AS bethesda_value_source, CASE  WHEN ((COALESCE(e.bethesda_category, c.category_num) IS NOT NULL)) THEN (NULL) WHEN (((e.bethesda_raw IS NOT NULL) AND (main."trim"(CAST(e.bethesda_raw AS VARCHAR)) != '') AND (TRY_CAST(main."trim"(CAST(e.bethesda_raw AS VARCHAR)) AS INTEGER) IS NULL))) THEN ('non_numeric_or_asterisk_bethesda_raw') WHEN (((e.pathology_diagnosis IS NOT NULL) AND (main."trim"(CAST(e.pathology_diagnosis AS VARCHAR)) != ''))) THEN ('pathology_present_bethesda_unparsed') ELSE 'no_episode_or_cytology_bethesda' END AS bethesda_unscorable_reason FROM fna_episode_master_v2 AS e LEFT JOIN cy AS c ON (((CAST(e.research_id AS BIGINT) = CAST(c.research_id AS BIGINT)) AND (CAST(e.fna_episode_id AS BIGINT) = CAST(c.fna_index AS BIGINT)) AND (c.rn = 1)));;

-- main.v_fna_surgery_window
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_fna_surgery_window" AS CREATE VIEW v_fna_surgery_window AS WITH patient_surgery_bounds AS (SELECT research_id, min(surgery_date) AS first_surgery_date, max(surgery_date) AS last_surgery_date, max(total_surgeries) AS total_surgeries FROM v_patient_surgery_timeline GROUP BY research_id), nearest_surgery AS (SELECT fem.research_id, fem.fna_episode_id, pst.surgery_episode_id AS nearest_surgery_episode_id, pst.surgery_date AS nearest_surgery_date, date_diff('day', pst.surgery_date, fem.resolved_fna_date) AS days_fna_to_nearest_surgery, row_number() OVER (PARTITION BY fem.research_id, fem.fna_episode_id ORDER BY abs(date_diff('day', fem.resolved_fna_date, pst.surgery_date)), pst.surgery_episode_id) AS rn FROM fna_episode_master_v2 AS fem INNER JOIN v_patient_surgery_timeline AS pst ON ((fem.research_id = pst.research_id)) WHERE ((fem.resolved_fna_date IS NOT NULL) AND (pst.surgery_date IS NOT NULL))), first_surgery_fallback AS (SELECT research_id, surgery_episode_id, surgery_date FROM v_patient_surgery_timeline WHERE (is_first_surgery = CAST('t' AS BOOLEAN)))SELECT fem.research_id, fem.fna_episode_id, fem.fna_date_native, fem.resolved_fna_date, fem.date_status, fem.date_confidence, fem.bethesda_raw, fem.bethesda_category, fem.pathology_diagnosis, fem.pathology_extended, fem.specimen_site_raw, fem.laterality, fem.linked_molecular_episode_id, fem.linked_imaging_nodule_id, fem.linked_surgery_episode_id, fem.source_table, fem.fna_confidence, COALESCE(ns.nearest_surgery_episode_id, fsf.surgery_episode_id) AS nearest_surgery_episode_id, COALESCE(ns.nearest_surgery_date, fsf.surgery_date) AS nearest_surgery_date, ns.days_fna_to_nearest_surgery, CASE  WHEN ((psb.research_id IS NULL)) THEN ('no_surgery') WHEN ((fem.resolved_fna_date IS NULL)) THEN ('pre_first_op') WHEN ((fem.resolved_fna_date < psb.first_surgery_date)) THEN ('pre_first_op') WHEN (((psb.total_surgeries > 1) AND (psb.first_surgery_date != psb.last_surgery_date) AND (fem.resolved_fna_date >= psb.first_surgery_date) AND (fem.resolved_fna_date < psb.last_surgery_date))) THEN ('inter_op') WHEN ((fem.resolved_fna_date >= COALESCE(psb.last_surgery_date, psb.first_surgery_date))) THEN ('post_final_op') ELSE 'post_final_op' END AS surgery_era, CASE  WHEN (((fem.resolved_fna_date IS NOT NULL) AND (psb.first_surgery_date IS NOT NULL) AND (fem.resolved_fna_date < psb.first_surgery_date))) THEN (date_diff('day', fem.resolved_fna_date, psb.first_surgery_date)) ELSE NULL END AS pre_op_days, CASE  WHEN (((fem.resolved_fna_date IS NOT NULL) AND (psb.last_surgery_date IS NOT NULL) AND (fem.resolved_fna_date >= psb.last_surgery_date))) THEN (date_diff('day', psb.last_surgery_date, fem.resolved_fna_date)) ELSE NULL END AS post_op_days FROM fna_episode_master_v2 AS fem LEFT JOIN patient_surgery_bounds AS psb ON ((fem.research_id = psb.research_id)) LEFT JOIN nearest_surgery AS ns ON (((fem.research_id = ns.research_id) AND (fem.fna_episode_id = ns.fna_episode_id) AND (ns.rn = 1))) LEFT JOIN first_surgery_fallback AS fsf ON (((fem.research_id = fsf.research_id) AND (ns.nearest_surgery_episode_id IS NULL) AND (psb.research_id IS NOT NULL)));;

-- main.v_imaging_nodule_linkage_classification_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_imaging_nodule_linkage_classification_v1" AS CREATE VIEW v_imaging_nodule_linkage_classification_v1 AS WITH prim AS (SELECT nodule_id, max(fna_episode_id) AS fna_episode_id FROM imaging_fna_linkage_mm_v1 WHERE is_primary_link GROUP BY 1), pfna AS (SELECT research_id, count_star() AS n_fna FROM fna_episode_master_v2 WHERE (COALESCE(fna_date_native, TRY_CAST(resolved_fna_date AS DATE)) IS NOT NULL) GROUP BY 1), fs AS (SELECT CAST(research_id AS BIGINT) AS research_id, min(TRY_CAST(surgery_date AS DATE)) AS first_surg FROM tumor_episode_master_v2 WHERE (research_id IS NOT NULL) GROUP BY 1), img AS (SELECT nodule_id, research_id, exam_id, CAST(exam_date AS DATE) AS exam_d FROM imaging_nodule_master_v1), enriched AS (SELECT i.nodule_id, i.research_id, i.exam_id, i.exam_d, p.fna_episode_id AS primary_linked_fna, COALESCE(pf.n_fna, 0) AS n_fna_episodes_patient, fs.first_surg, EXISTS(SELECT 1 FROM fna_episode_master_v2 AS f WHERE ((CAST(f.research_id AS BIGINT) = CAST(i.research_id AS BIGINT)) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) IS NOT NULL) AND (i.exam_d IS NOT NULL) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) >= i.exam_d) AND (datediff('day', i.exam_d, COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE))) BETWEEN 0 AND 90))) AS has_fna_calendar_0_90d_after_exam, EXISTS(SELECT 1 FROM fna_episode_master_v2 AS f WHERE ((CAST(f.research_id AS BIGINT) = CAST(i.research_id AS BIGINT)) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) IS NOT NULL) AND (i.exam_d IS NOT NULL) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) >= i.exam_d) AND (datediff('day', i.exam_d, COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE))) BETWEEN 0 AND 90) AND ((fs.first_surg IS NULL) OR ((i.exam_d <= fs.first_surg) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) <= fs.first_surg))))) AS has_fna_0_90d_after_exam, (NOT EXISTS(SELECT 1 FROM fna_episode_master_v2 AS f WHERE ((CAST(f.research_id AS BIGINT) = CAST(i.research_id AS BIGINT)) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) IS NOT NULL) AND (i.exam_d IS NOT NULL) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) >= i.exam_d)))) AS all_fna_strictly_before_exam, EXISTS(SELECT 1 FROM fna_episode_master_v2 AS f WHERE ((CAST(f.research_id AS BIGINT) = CAST(i.research_id AS BIGINT)) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) IS NOT NULL) AND (i.exam_d IS NOT NULL) AND (COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE)) >= i.exam_d) AND (datediff('day', i.exam_d, COALESCE(f.fna_date_native, TRY_CAST(f.resolved_fna_date AS DATE))) > 90))) AS has_fna_after_exam_beyond_90d, EXISTS(SELECT 1 FROM imaging_fna_linkage_mm_v1 AS mm WHERE ((mm.nodule_id = i.nodule_id) AND (mm.day_gap_us_before_fna BETWEEN 0 AND 90))) AS has_mm_pair_0_90d_for_nodule FROM img AS i LEFT JOIN prim AS p ON ((i.nodule_id = p.nodule_id)) LEFT JOIN pfna AS pf ON ((CAST(i.research_id AS BIGINT) = CAST(pf.research_id AS BIGINT))) LEFT JOIN fs ON ((CAST(i.research_id AS BIGINT) = CAST(fs.research_id AS BIGINT))))SELECT nodule_id, research_id, exam_id, exam_d, primary_linked_fna, CASE  WHEN ((primary_linked_fna IS NOT NULL)) THEN ('linked_to_fna') WHEN ((COALESCE(n_fna_episodes_patient, 0) = 0)) THEN ('no_eligible_fna') WHEN (((exam_d IS NOT NULL) AND (first_surg IS NOT NULL) AND (exam_d > first_surg))) THEN ('no_eligible_fna') WHEN (all_fna_strictly_before_exam) THEN ('no_eligible_fna') WHEN ((COALESCE(has_fna_calendar_0_90d_after_exam, CAST('f' AS BOOLEAN)) AND (NOT COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN))))) THEN ('no_eligible_fna') WHEN ((COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN)) AND COALESCE(has_mm_pair_0_90d_for_nodule, CAST('f' AS BOOLEAN)))) THEN ('unresolved_linkage_gap') WHEN (COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN))) THEN ('no_eligible_fna') WHEN ((has_fna_after_exam_beyond_90d AND (NOT COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN))))) THEN ('no_eligible_fna') ELSE 'unresolved_linkage_gap' END AS linkage_state, CASE  WHEN ((primary_linked_fna IS NOT NULL)) THEN ('primary_row_in_imaging_fna_linkage_mm_v1') WHEN ((COALESCE(n_fna_episodes_patient, 0) = 0)) THEN ('patient_has_no_dated_fna_episode') WHEN (((exam_d IS NOT NULL) AND (first_surg IS NOT NULL) AND (exam_d > first_surg))) THEN ('index_us_after_first_surgery') WHEN (all_fna_strictly_before_exam) THEN ('all_fna_before_index_us_exam') WHEN ((COALESCE(has_fna_calendar_0_90d_after_exam, CAST('f' AS BOOLEAN)) AND (NOT COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN))))) THEN ('fna_calendar_in_window_but_not_preop') WHEN ((COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN)) AND COALESCE(has_mm_pair_0_90d_for_nodule, CAST('f' AS BOOLEAN)))) THEN ('mm_pair_0_90d_no_primary_ambiguous_or_all_false_primary') WHEN (COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN))) THEN ('preop_fna_window_patient_no_mm_pair_for_this_nodule') WHEN ((has_fna_after_exam_beyond_90d AND (NOT COALESCE(has_fna_0_90d_after_exam, CAST('f' AS BOOLEAN))))) THEN ('only_fna_beyond_90d_after_index_us') ELSE 'ambiguous_requires_manual_review' END AS linkage_reason_code FROM enriched;;

-- main.v_imaging_nodule_tirads_gap_v1
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_imaging_nodule_tirads_gap_v1" AS CREATE VIEW v_imaging_nodule_tirads_gap_v1 AS SELECT m.nodule_id, m.research_id, m.exam_date, ((((CASE  WHEN (((m.composition IS NOT NULL) AND (main."trim"(CAST(m.composition AS VARCHAR)) != ''))) THEN (1) ELSE 0 END + CASE  WHEN (((m.echogenicity IS NOT NULL) AND (main."trim"(CAST(m.echogenicity AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) + CASE  WHEN (((m.shape IS NOT NULL) AND (main."trim"(CAST(m.shape AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) + CASE  WHEN (((m.margins IS NOT NULL) AND (main."trim"(CAST(m.margins AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) + CASE  WHEN (((m.calcifications IS NOT NULL) AND (main."trim"(CAST(m.calcifications AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) AS n_populated_acr_fields, m.tirads_reported, m.tirads_acr_recalculated, CASE  WHEN (((((((CASE  WHEN (((m.composition IS NOT NULL) AND (main."trim"(CAST(m.composition AS VARCHAR)) != ''))) THEN (1) ELSE 0 END + CASE  WHEN (((m.echogenicity IS NOT NULL) AND (main."trim"(CAST(m.echogenicity AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) + CASE  WHEN (((m.shape IS NOT NULL) AND (main."trim"(CAST(m.shape AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) + CASE  WHEN (((m.margins IS NOT NULL) AND (main."trim"(CAST(m.margins AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) + CASE  WHEN (((m.calcifications IS NOT NULL) AND (main."trim"(CAST(m.calcifications AS VARCHAR)) != ''))) THEN (1) ELSE 0 END) >= 5) AND (m.tirads_reported IS NULL) AND (m.tirads_acr_recalculated IS NULL))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS gap_sufficient_features_null_scores FROM imaging_nodule_master_v1 AS m;;

-- main.v_patient_surgery_timeline
CREATE SCHEMA IF NOT EXISTS "main";
CREATE OR REPLACE VIEW "main"."v_patient_surgery_timeline" AS CREATE VIEW v_patient_surgery_timeline AS SELECT research_id, surgery_episode_id, TRY_CAST(resolved_surgery_date AS DATE) AS surgery_date, row_number() OVER (PARTITION BY research_id ORDER BY TRY_CAST(resolved_surgery_date AS DATE), surgery_episode_id) AS surgery_ordinal, count() OVER (PARTITION BY research_id) AS total_surgeries, (row_number() OVER (PARTITION BY research_id ORDER BY TRY_CAST(resolved_surgery_date AS DATE), surgery_episode_id) = 1) AS is_first_surgery, (row_number() OVER (PARTITION BY research_id ORDER BY TRY_CAST(resolved_surgery_date AS DATE), surgery_episode_id) = count() OVER (PARTITION BY research_id)) AS is_last_surgery, lead(TRY_CAST(resolved_surgery_date AS DATE)) OVER (PARTITION BY research_id ORDER BY TRY_CAST(resolved_surgery_date AS DATE), surgery_episode_id) AS next_surgery_date, lag(TRY_CAST(resolved_surgery_date AS DATE)) OVER (PARTITION BY research_id ORDER BY TRY_CAST(resolved_surgery_date AS DATE), surgery_episode_id) AS prev_surgery_date FROM operative_episode_detail_v2;;

-- mm_contract_dev.val_multi_tumor_report_mm_v1
CREATE SCHEMA IF NOT EXISTS "mm_contract_dev";
CREATE OR REPLACE VIEW "mm_contract_dev"."val_multi_tumor_report_mm_v1" AS CREATE VIEW mm_contract_dev.val_multi_tumor_report_mm_v1 AS SELECT * FROM mm_contract_dev.val_multitumor_expansion_mm_v1;;

-- qa.date_provenance_completeness_v
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."date_provenance_completeness_v" AS CREATE VIEW qa.date_provenance_completeness_v AS SELECT domain_name, total_rows, unique_patients, entity_date_fill_pct, note_date_fill_pct, provenance_cols_present, CASE  WHEN (((entity_date_fill_pct >= 50) AND (note_date_fill_pct >= 50))) THEN ('adequate') WHEN (((entity_date_fill_pct >= 30) OR (note_date_fill_pct >= 30))) THEN ('marginal') ELSE 'insufficient' END AS completeness_tier, run_label FROM qa.domain_validation WHERE (run_label = (SELECT max(run_label) FROM qa.domain_validation));;

-- qa.domain_validation_summary_v
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."domain_validation_summary_v" AS CREATE VIEW qa.domain_validation_summary_v AS SELECT run_label, count_star() AS domains_checked, count_star() FILTER (WHERE schema_ok) AS schema_ok_count, sum(total_rows) AS total_rows_all_domains, sum(unique_patients) AS total_patients_all_domains, avg(dup_rate) AS avg_dup_rate, max(dup_rate) AS max_dup_rate, avg(entity_date_fill_pct) AS avg_entity_date_fill, min(entity_date_fill_pct) AS min_entity_date_fill, avg(note_date_fill_pct) AS avg_note_date_fill, max(generated_at) AS last_run FROM qa.domain_validation GROUP BY run_label;;

-- qa.manual_review_queue_summary_v
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."manual_review_queue_summary_v" AS CREATE VIEW qa.manual_review_queue_summary_v AS SELECT run_label, "domain", count_star() AS total_items, count_star() FILTER (WHERE (verification_status IS NOT NULL)) AS reviewed, count_star() FILTER (WHERE (verification_status IS NULL)) AS pending, count(DISTINCT research_id) AS unique_patients FROM qa.manual_review_queue GROUP BY run_label, "domain";;

-- qa.promotion_scorecard_summary_v
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."promotion_scorecard_summary_v" AS CREATE VIEW qa.promotion_scorecard_summary_v AS SELECT run_label, count_star() AS total_gates, count_star() FILTER (WHERE (status = 'PASS')) AS passed, count_star() FILTER (WHERE (status = 'FAIL')) AS failed, count_star() FILTER (WHERE (status NOT IN ('PASS', 'FAIL'))) AS conditional, max(generated_at) AS last_run FROM qa.promotion_scorecard GROUP BY run_label;;

-- qa.v_diag_specimen_duplicate_focus_fp_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_duplicate_focus_fp_v1" AS CREATE VIEW qa.v_diag_specimen_duplicate_focus_fp_v1 AS SELECT focus_fingerprint_sha256 AS fingerprint, CAST(count_star() AS BIGINT) AS row_count FROM main.specimen_tumor_focus_v1 GROUP BY 1 HAVING (count_star() > 1);;

-- qa.v_diag_specimen_duplicate_master_fp_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_duplicate_master_fp_v1" AS CREATE VIEW qa.v_diag_specimen_duplicate_master_fp_v1 AS SELECT specimen_fingerprint_sha256 AS fingerprint, count_star() AS row_count FROM main.specimen_master_v1 GROUP BY 1 HAVING (count_star() > 1);;

-- qa.v_diag_specimen_fhir_broken_refs_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_fhir_broken_refs_v1" AS CREATE VIEW qa.v_diag_specimen_fhir_broken_refs_v1 AS (SELECT CAST('specimen_subject' AS VARCHAR) AS issue, specimen_id AS anchor_id, json_extract_string(resource_json, '$.subject.reference') AS ref_value, ('Patient/' || regexp_replace(main."trim"(COALESCE(fs.patient_fhir_id, '')), '^(Patient/)+', '')) AS expected_ref FROM main.fhir_specimen_v1 AS fs WHERE (regexp_replace(COALESCE(json_extract_string(resource_json, '$.subject.reference'), ''), '^(Patient/)+', '') IS DISTINCT FROM regexp_replace(main."trim"(COALESCE(fs.patient_fhir_id, '')), '^(Patient/)+', ''))) UNION ALL ((((SELECT CAST('specimen_collection_procedure' AS VARCHAR), specimen_id, json_extract_string(resource_json, '$.collection.procedure.reference'), ('Procedure/' || main."substring"(sha256(concat('proc|', fs.specimen_id)), 1, 16)) FROM main.fhir_specimen_v1 AS fs WHERE ((json_extract_string(resource_json, '$.collection.procedure.reference') IS NOT NULL) AND (json_extract_string(resource_json, '$.collection.procedure.reference') IS DISTINCT FROM ('Procedure/' || main."substring"(sha256(concat('proc|', fs.specimen_id)), 1, 16))))) UNION ALL (SELECT CAST('procedure_subject' AS VARCHAR), fp.specimen_id, json_extract_string(fp.resource_json, '$.subject.reference'), ('Patient/' || regexp_replace(main."trim"(COALESCE(fp.patient_fhir_id, '')), '^(Patient/)+', '')) AS expected_ref FROM main.fhir_procedure_collection_v1 AS fp WHERE (regexp_replace(COALESCE(json_extract_string(fp.resource_json, '$.subject.reference'), ''), '^(Patient/)+', '') IS DISTINCT FROM regexp_replace(main."trim"(COALESCE(fp.patient_fhir_id, '')), '^(Patient/)+', '')))) UNION ALL ((SELECT CAST('procedure_encounter' AS VARCHAR), fp.specimen_id, json_extract_string(fp.resource_json, '$.encounter.reference'), ('Encounter/' || main."substring"(sha256(concat('enc|', fp.specimen_id)), 1, 16)) FROM main.fhir_procedure_collection_v1 AS fp WHERE ((json_extract_string(fp.resource_json, '$.encounter.reference') IS NOT NULL) AND (json_extract_string(fp.resource_json, '$.encounter.reference') IS DISTINCT FROM ('Encounter/' || main."substring"(sha256(concat('enc|', fp.specimen_id)), 1, 16))))) UNION ALL (SELECT CAST('encounter_subject' AS VARCHAR), fe.specimen_id, json_extract_string(fe.resource_json, '$.subject.reference'), ('Patient/' || regexp_replace(main."trim"(COALESCE(fe.patient_fhir_id, '')), '^(Patient/)+', '')) AS expected_ref FROM main.fhir_encounter_v1 AS fe WHERE (regexp_replace(COALESCE(json_extract_string(fe.resource_json, '$.subject.reference'), ''), '^(Patient/)+', '') IS DISTINCT FROM regexp_replace(main."trim"(COALESCE(fe.patient_fhir_id, '')), '^(Patient/)+', ''))))) UNION ALL ((SELECT CAST('encounter_episode' AS VARCHAR), fe.specimen_id, json_extract_string(fe.resource_json, '$.episodeOfCare[0].reference'), fo.fhir_id AS expected_ref FROM main.fhir_encounter_v1 AS fe LEFT JOIN main.fhir_episode_of_care_v1 AS fo ON ((fo.fhir_id = json_extract_string(fe.resource_json, '$.episodeOfCare[0].reference'))) WHERE ((json_extract_string(fe.resource_json, '$.episodeOfCare[0].reference') IS NOT NULL) AND (fo.fhir_id IS NULL))) UNION ALL (SELECT CAST('encounter_episode_patient_mismatch' AS VARCHAR), fe.specimen_id, CAST(fe.patient_fhir_id AS VARCHAR), CAST(fo.patient_fhir_id AS VARCHAR) FROM main.fhir_encounter_v1 AS fe INNER JOIN main.fhir_episode_of_care_v1 AS fo ON ((fo.fhir_id = json_extract_string(fe.resource_json, '$.episodeOfCare[0].reference'))) WHERE ((json_extract_string(fe.resource_json, '$.episodeOfCare[0].reference') IS NOT NULL) AND (fo.patient_fhir_id IS DISTINCT FROM fe.patient_fhir_id)))));;

-- qa.v_diag_specimen_fhir_bundle_entry_drift_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_fhir_bundle_entry_drift_v1" AS CREATE VIEW qa.v_diag_specimen_fhir_bundle_entry_drift_v1 AS SELECT b.bundle_ix, b.specimen_id, r.idx AS entry_idx, json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].url')) AS entry_url, concat(json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].resource.resourceType')), '/', json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].resource.id'))) AS expected_url FROM main.fhir_bundle_specimen_export_v1 AS b CROSS JOIN (SELECT * FROM (SELECT * FROM (VALUES (CAST(0 AS BIGINT)), (CAST(1 AS BIGINT)), (CAST(2 AS BIGINT)), (CAST(3 AS BIGINT))) AS valueslist) AS valueslist) AS r(idx) WHERE ((json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].url')) IS DISTINCT FROM concat(json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].resource.resourceType')), '/', json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].resource.id')))) OR ((json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].url')) IS NULL) AND ((json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].resource.id')) IS NOT NULL) OR (json_extract_string(b.bundle_json, (('$.entry[' || CAST(r.idx AS VARCHAR)) || '].resource.resourceType')) IS NOT NULL))));;

-- qa.v_diag_specimen_genomics_A_tier_requires_specimen_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_genomics_A_tier_requires_specimen_v1" AS CREATE VIEW qa.v_diag_specimen_genomics_A_tier_requires_specimen_v1 AS SELECT genomic_assay_id, research_id, specimen_id, specimen_focus_id, binding_confidence_tier FROM main.specimen_genomic_assay_v1 WHERE ((binding_confidence_tier = 'A_exact_high') AND ((specimen_id IS NULL) OR (specimen_focus_id IS NULL)));;

-- qa.v_diag_specimen_genomics_dupe_thyroseq_slice_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_genomics_dupe_thyroseq_slice_v1" AS CREATE VIEW qa.v_diag_specimen_genomics_dupe_thyroseq_slice_v1 AS SELECT research_id, molecular_episode_id, payload_field, payload_explode_ord, CAST(count_star() AS BIGINT) AS row_count FROM main.specimen_genomic_assay_v1 WHERE (source_table = 'thyroseq_molecular_enrichment+json_each') GROUP BY 1, 2, 3, 4 HAVING (count_star() > 1);;

-- qa.v_diag_specimen_genomics_thyroseq_ordinality_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_genomics_thyroseq_ordinality_v1" AS CREATE VIEW qa.v_diag_specimen_genomics_thyroseq_ordinality_v1 AS SELECT genomic_assay_id, research_id, payload_field, payload_explode_ord FROM main.specimen_genomic_assay_v1 WHERE ((source_table = 'thyroseq_molecular_enrichment+json_each') AND (payload_field IS NOT NULL) AND (main."trim"(CAST(payload_field AS VARCHAR)) != '') AND ((payload_explode_ord IS NULL) OR (payload_explode_ord < 1)));;

-- qa.v_diag_specimen_genomics_tier_enum_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_genomics_tier_enum_v1" AS CREATE VIEW qa.v_diag_specimen_genomics_tier_enum_v1 AS (SELECT genomic_assay_id, research_id, linkage_confidence_tier, binding_confidence_tier, CAST('bad_linkage_tier' AS VARCHAR) AS violation FROM main.specimen_genomic_assay_v1 WHERE ((linkage_confidence_tier IS NULL) OR (linkage_confidence_tier NOT IN ('exact', 'high_confidence', 'plausible_review', 'unresolved_review')))) UNION ALL (SELECT genomic_assay_id, research_id, linkage_confidence_tier, binding_confidence_tier, CAST('bad_binding_tier' AS VARCHAR) FROM main.specimen_genomic_assay_v1 WHERE ((binding_confidence_tier IS NULL) OR (binding_confidence_tier NOT IN ('A_exact_high', 'B_specimen_only', 'C_review', 'D_unlinked'))));;

-- qa.v_diag_specimen_orphan_focus_master_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_orphan_focus_master_v1" AS CREATE VIEW qa.v_diag_specimen_orphan_focus_master_v1 AS SELECT f.specimen_focus_id, f.specimen_id, f.research_id, CAST('missing_master' AS VARCHAR) AS reason FROM main.specimen_tumor_focus_v1 AS f LEFT JOIN main.specimen_master_v1 AS m ON ((f.specimen_id = m.specimen_id)) WHERE (m.specimen_id IS NULL);;

-- qa.v_diag_specimen_orphan_focus_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_orphan_focus_v1" AS CREATE VIEW qa.v_diag_specimen_orphan_focus_v1 AS SELECT f.specimen_focus_id, f.specimen_id, f.research_id FROM main.specimen_tumor_focus_v1 AS f LEFT JOIN main.specimen_master_v1 AS m ON ((f.specimen_id = m.specimen_id)) WHERE (m.specimen_id IS NULL);;

-- qa.v_diag_specimen_orphan_genomic_focus_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_orphan_genomic_focus_v1" AS CREATE VIEW qa.v_diag_specimen_orphan_genomic_focus_v1 AS SELECT g.genomic_assay_id, g.specimen_id, g.specimen_focus_id, g.research_id, CAST('missing_focus' AS VARCHAR) AS reason FROM main.specimen_genomic_assay_v1 AS g LEFT JOIN main.specimen_tumor_focus_v1 AS f ON ((g.specimen_focus_id = f.specimen_focus_id)) WHERE ((g.specimen_focus_id IS NOT NULL) AND (f.specimen_focus_id IS NULL));;

-- qa.v_diag_specimen_orphan_genomic_master_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_orphan_genomic_master_v1" AS CREATE VIEW qa.v_diag_specimen_orphan_genomic_master_v1 AS SELECT g.genomic_assay_id, g.specimen_id, g.specimen_focus_id, g.research_id, CAST('missing_master' AS VARCHAR) AS reason FROM main.specimen_genomic_assay_v1 AS g LEFT JOIN main.specimen_master_v1 AS m ON ((g.specimen_id = m.specimen_id)) WHERE ((g.specimen_id IS NOT NULL) AND (m.specimen_id IS NULL));;

-- qa.v_diag_specimen_orphan_genomic_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_orphan_genomic_v1" AS CREATE VIEW qa.v_diag_specimen_orphan_genomic_v1 AS (SELECT g.genomic_assay_id, g.specimen_id, g.specimen_focus_id, g.research_id, CAST('missing_master' AS VARCHAR) AS reason FROM main.specimen_genomic_assay_v1 AS g LEFT JOIN main.specimen_master_v1 AS m ON ((g.specimen_id = m.specimen_id)) WHERE ((g.specimen_id IS NOT NULL) AND (m.specimen_id IS NULL))) UNION ALL (SELECT g.genomic_assay_id, g.specimen_id, g.specimen_focus_id, g.research_id, CAST('missing_focus' AS VARCHAR) AS reason FROM main.specimen_genomic_assay_v1 AS g LEFT JOIN main.specimen_tumor_focus_v1 AS f ON ((g.specimen_focus_id = f.specimen_focus_id)) WHERE ((g.specimen_focus_id IS NOT NULL) AND (f.specimen_focus_id IS NULL)));;

-- qa.v_diag_specimen_provenance_focus_gaps_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_provenance_focus_gaps_v1" AS CREATE VIEW qa.v_diag_specimen_provenance_focus_gaps_v1 AS SELECT specimen_focus_id, specimen_id, research_id, CAST('missing_identity_run' AS VARCHAR) AS reason FROM main.specimen_tumor_focus_v1 WHERE (main."trim"(COALESCE(identity_build_run_id, '')) = '');;

-- qa.v_diag_specimen_provenance_focus_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_provenance_focus_v1" AS CREATE VIEW qa.v_diag_specimen_provenance_focus_v1 AS SELECT CAST(count_star() FILTER (WHERE (main."trim"(COALESCE(identity_build_run_id, '')) = '')) AS BIGINT) AS n_missing_identity_run, CAST(count_star() AS BIGINT) AS n_rows FROM main.specimen_tumor_focus_v1;;

-- qa.v_diag_specimen_provenance_genomic_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_provenance_genomic_v1" AS CREATE VIEW qa.v_diag_specimen_provenance_genomic_v1 AS SELECT CAST(count_star() FILTER (WHERE ((linkage_confidence_tier IN ('exact', 'high_confidence')) AND (specimen_id IS NULL))) AS BIGINT) AS n_high_tier_null_specimen, CAST(count_star() AS BIGINT) AS n_rows FROM main.specimen_genomic_assay_v1;;

-- qa.v_diag_specimen_provenance_master_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_provenance_master_v1" AS CREATE VIEW qa.v_diag_specimen_provenance_master_v1 AS SELECT CAST(count_star() FILTER (WHERE (main."trim"(COALESCE(identity_build_run_id, '')) = '')) AS BIGINT) AS n_missing_identity_run, CAST(count_star() AS BIGINT) AS n_rows FROM main.specimen_master_v1;;

-- qa.v_diag_specimen_provenance_summary_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_provenance_summary_v1" AS CREATE VIEW qa.v_diag_specimen_provenance_summary_v1 AS SELECT m.n_master_missing_identity_run, m.n_master_rows, f.n_focus_missing_identity_run, f.n_focus_rows, g.n_genomic_high_tier_null_specimen FROM (SELECT CAST(count_star() FILTER (WHERE (main."trim"(COALESCE(identity_build_run_id, '')) = '')) AS BIGINT) AS n_master_missing_identity_run, CAST(count_star() AS BIGINT) AS n_master_rows FROM main.specimen_master_v1) AS m , (SELECT CAST(count_star() FILTER (WHERE (main."trim"(COALESCE(identity_build_run_id, '')) = '')) AS BIGINT) AS n_focus_missing_identity_run, CAST(count_star() AS BIGINT) AS n_focus_rows FROM main.specimen_tumor_focus_v1) AS f , (SELECT CAST(count_star() FILTER (WHERE ((linkage_confidence_tier IN ('exact', 'high_confidence')) AND (specimen_id IS NULL))) AS BIGINT) AS n_genomic_high_tier_null_specimen FROM main.specimen_genomic_assay_v1) AS g;;

-- qa.v_diag_specimen_review_burden_v1
CREATE SCHEMA IF NOT EXISTS "qa";
CREATE OR REPLACE VIEW "qa"."v_diag_specimen_review_burden_v1" AS CREATE VIEW qa.v_diag_specimen_review_burden_v1 AS SELECT CAST('specimen_genomic_link_review' AS VARCHAR) AS queue_key, CAST(COALESCE(review_status, 'unknown') AS VARCHAR) AS review_status, CAST(count_star() AS BIGINT) AS n_rows FROM qa.specimen_genomic_link_review_v1 GROUP BY 1, 2;;

